// Aceita entrada tanto do Execute Workflow Trigger (passthrough: { decisao, id_decisao })
// quanto do Webhook de teste ({ body: { decisao, id_decisao }, headers, query }).
const item = $input.first().json;
const viaWebhook = Object.prototype.hasOwnProperty.call(item, 'body');
const src = viaWebhook ? item.body : item;
const decisao = src.decisao || {};
const idDecisao = src.id_decisao !== undefined ? src.id_decisao : null;

return [{
  json: {
    decisao,
    id_decisao: idDecisao,
    via_webhook: viaWebhook
  }
}];

// Rótulos e emojis copiados literalmente de config/limiares.json::status.rotulos
// (não lidos em runtime — ver desvio documentado no relatório de entrega do T08).
const ROTULOS = { NORMAL: 'NORMAL', ATENCAO: 'ATEN\u00c7\u00c3O', CRITICO: 'CR\u00cdTICO' };
const EMOJIS = { NORMAL: '\ud83d\udfe2', ATENCAO: '\ud83d\udfe1', CRITICO: '\ud83d\udd34' };
const NOMES_CANAL = { TELEGRAM: 'Telegram', EMAIL: 'E-mail', TRELLO: 'OS no Trello' };

// Enviado com parse_mode HTML: todo texto vindo da decisão é escapado
// (MOTOR_01 quebraria o parse em Markdown por causa do '_').
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const d = $json.decisao;
const idDecisao = $json.id_decisao;
const statusFinal = d.status_final;
const rotulo = ROTULOS[statusFinal] || statusFinal;
const emoji = EMOJIS[statusFinal] || '';

const acoes = Array.isArray(d.acoes_previstas) ? d.acoes_previstas : [];
const acoesTexto = acoes.map((c) => NOMES_CANAL[c] || c).join(' + ');

const linhas = [];
if (d.relatorio) {
  // Formato do enunciado (contracts/guardrail.js::relatorioTexto), seguido da análise do agente.
  linhas.push(`${emoji} <b>${esc(d.situacao || rotulo)} \u2014 ${esc(d.id_maquina)}</b>`);
  linhas.push(esc(d.relatorio));
  if (d.resumo_operador) linhas.push('', `<i>An\u00e1lise do agente:</i> ${esc(d.resumo_operador)}`);
} else {
linhas.push(`${emoji} <b>${rotulo} \u2014 ${esc(d.id_maquina)}</b>`);
if (d.resumo_operador) linhas.push(esc(d.resumo_operador));
}
if (acoesTexto) linhas.push(`A\u00e7\u00f5es: ${acoesTexto}`);

if (d.requer_humano) {
  linhas.push('\ud83d\udc64 Verifica\u00e7\u00e3o humana necess\u00e1ria');
  const motivo = (d.justificativa || '').trim();
  if (motivo) {
    const motivoCurto = motivo.length > 180 ? motivo.slice(0, 177) + '...' : motivo;
    linhas.push(`Motivo: ${esc(motivoCurto)}`);
  }
}

let hh = '--';
let mm = '--';
if (d.ts) {
  const dt = new Date(d.ts);
  if (!isNaN(dt.getTime())) {
    hh = String(dt.getHours()).padStart(2, '0');
    mm = String(dt.getMinutes()).padStart(2, '0');
  }
}
linhas.push(`Decis\u00e3o #${idDecisao} \u00b7 ${hh}:${mm}`);

const mensagem = linhas.filter((l) => l !== undefined && l !== null).join('\n').replace(/\n{3,}/g, '\n\n');

return [{ json: { ...$json, mensagem_telegram: mensagem } }];

// Relatório HTML do e-mail (CRÍTICO). Deve renderizar bem mesmo com
// decisao.especialistas todos null (fase sem LLM).
const ROTULOS = { NORMAL: 'NORMAL', ATENCAO: 'ATEN\u00c7\u00c3O', CRITICO: 'CR\u00cdTICO' };
const NOMES_ESPECIALISTAS = { manutencao: 'Manuten\u00e7\u00e3o', producao: 'Produ\u00e7\u00e3o', energia: 'Energia' };

const d = $json.decisao;
const idDecisao = $json.id_decisao;
const rotulo = ROTULOS[d.status_final] || d.status_final;

function esc(s) {
  if (s === null || s === undefined) return '';
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const especialistas = d.especialistas || {};

function achadosRows(parecer) {
  if (!parecer || !Array.isArray(parecer.achados) || parecer.achados.length === 0) {
    return '<tr><td colspan="4" style="padding:6px;color:#777;">Sem grandezas registradas.</td></tr>';
  }
  return parecer.achados.map((a) => `
    <tr>
      <td style="padding:6px;border-bottom:1px solid #eee;">${esc(a.grandeza)}</td>
      <td style="padding:6px;border-bottom:1px solid #eee;">${a.valor === null || a.valor === undefined ? '-' : esc(a.valor)}</td>
      <td style="padding:6px;border-bottom:1px solid #eee;">${esc(a.status)}</td>
      <td style="padding:6px;border-bottom:1px solid #eee;">${esc(a.observacao)}</td>
    </tr>`).join('');
}

function blocoParecer(chave) {
  const parecer = especialistas[chave];
  const titulo = NOMES_ESPECIALISTAS[chave];
  if (!parecer) {
    return `<h3 style="margin:16px 0 6px;">${titulo}</h3><p style="color:#777;margin:0 0 12px;">Parecer n\u00e3o dispon\u00edvel (LLM n\u00e3o consultado ou falhou).</p>`;
  }
  return `
    <h3 style="margin:16px 0 6px;">${titulo} \u2014 <span style="font-weight:normal;">${esc(parecer.status)}</span></h3>
    <table style="border-collapse:collapse;width:100%;font-size:13px;margin-bottom:8px;">
      <thead><tr style="background:#f5f5f5;">
        <th style="text-align:left;padding:6px;">Grandeza</th>
        <th style="text-align:left;padding:6px;">Valor</th>
        <th style="text-align:left;padding:6px;">Status</th>
        <th style="text-align:left;padding:6px;">Observa\u00e7\u00e3o</th>
      </tr></thead>
      <tbody>${achadosRows(parecer)}</tbody>
    </table>
    <p style="margin:0 0 4px;"><strong>Recomenda\u00e7\u00e3o:</strong> ${esc(parecer.recomendacao || '-')}</p>
    <p style="margin:0;color:#555;font-size:12px;">Confian\u00e7a: ${esc(parecer.confianca || '-')} \u00b7 Dados insuficientes: ${parecer.dados_insuficientes ? 'sim' : 'n\u00e3o'}</p>
  `;
}

const problemasHtml = Array.isArray(d.problemas) && d.problemas.length
  ? '<p style="margin:0 0 4px;"><strong>Problemas identificados:</strong></p><ul style="margin:0 0 12px;">' +
    d.problemas.map((p) => '<li>' + esc(p.descricao) + (p.valor !== null && p.valor !== undefined ? ' (' + esc(p.valor) + '; limite ' + esc(p.limite) + ')' : '') + '</li>').join('') + '</ul>'
  : '';
const blocoSituacao = d.situacao
  ? '<h3 style="margin:0 0 6px;">Situação: ' + esc(d.situacao) + '</h3>' + problemasHtml +
    (d.recomendacao ? '<p style="margin:0 0 16px;"><strong>RECOMENDAÇÃO:</strong> ' + esc(d.recomendacao) + '</p>' : '')
  : '';

const html = `<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"></head>
<body style="font-family:Arial,Helvetica,sans-serif;color:#222;max-width:640px;margin:0 auto;padding:16px;">
  <h2 style="margin:0 0 4px;">[CP5] ${esc(rotulo)} \u2014 ${esc(d.id_maquina)}</h2>
  <p style="margin:0 0 16px;color:#555;">Decis\u00e3o #${esc(idDecisao)} \u00b7 ${esc(d.ts)}</p>

  <table style="border-collapse:collapse;margin-bottom:16px;font-size:13px;">
    <tr><td style="padding:4px 12px 4px 0;color:#555;">Status guardrail</td><td style="padding:4px;"><strong>${esc(d.status_guardrail)}</strong></td></tr>
    <tr><td style="padding:4px 12px 4px 0;color:#555;">Status LLM</td><td style="padding:4px;"><strong>${d.status_llm === null || d.status_llm === undefined ? 'n\u00e3o consultado' : esc(d.status_llm)}</strong></td></tr>
    <tr><td style="padding:4px 12px 4px 0;color:#555;">Status final</td><td style="padding:4px;"><strong>${esc(rotulo)}</strong></td></tr>
    <tr><td style="padding:4px 12px 4px 0;color:#555;">Requer verifica\u00e7\u00e3o humana</td><td style="padding:4px;"><strong>${d.requer_humano ? 'sim' : 'n\u00e3o'}</strong></td></tr>
  </table>

  ${blocoSituacao}

  <h3 style="margin:0 0 6px;">Resumo</h3>
  <p style="margin:0 0 16px;">${esc(d.resumo_operador)}</p>

  <h3 style="margin:0 0 6px;">Justificativa</h3>
  <p style="margin:0 0 16px;white-space:pre-wrap;">${esc(d.justificativa)}</p>

  <h3 style="margin:16px 0 6px;border-top:1px solid #ddd;padding-top:12px;">Pareceres dos especialistas</h3>
  ${blocoParecer('manutencao')}
  ${blocoParecer('producao')}
  ${blocoParecer('energia')}

  <p style="margin-top:24px;padding-top:12px;border-top:1px solid #ddd;color:#888;font-size:11px;">
    Relat\u00f3rio gerado automaticamente \u2014 decis\u00e3o final sob responsabilidade da equipe de manuten\u00e7\u00e3o.
  </p>
</body></html>`;

const assunto = `[CP5][${d.situacao || rotulo}] ${d.id_maquina} \u2014 Relat\u00f3rio de diagn\u00f3stico #${idDecisao}`;

return [{ json: { ...$json, assunto_email: assunto, html_email: html } }];

// Card de ordem de servi\u00e7o do Trello (CR\u00cdTICO). requer_humano => sem TRELLO
// j\u00e1 vem garantido por decisao.acoes_previstas (n\u00e3o recalculado aqui).
const NOMES_ESPECIALISTAS = { manutencao: 'Manuten\u00e7\u00e3o', producao: 'Produ\u00e7\u00e3o', energia: 'Energia' };

const d = $json.decisao;
const idDecisao = $json.id_decisao;

const especialistas = d.especialistas || {};

function evidenciasParecer(chave) {
  const p = especialistas[chave];
  const titulo = NOMES_ESPECIALISTAS[chave];
  if (!p) return `**${titulo}:** parecer n\u00e3o dispon\u00edvel.`;
  const achados = Array.isArray(p.achados) && p.achados.length
    ? p.achados.map((a) => `  - ${a.grandeza}: ${a.valor === null || a.valor === undefined ? '-' : a.valor} (${a.status}) \u2014 ${a.observacao || ''}`).join('\n')
    : '  - sem grandezas registradas.';
  return `**${titulo}** (${p.status}):\n${achados}`;
}

const titulo = `[ALTA] Inspe\u00e7\u00e3o urgente \u2014 ${d.id_maquina} (#${idDecisao})`;

const problemasTxt = Array.isArray(d.problemas) && d.problemas.length ? d.problemas.map((p) => '- ' + p.descricao).join('\n') : '-';
const descricao = `### Problemas identificados
${problemasTxt}

### Recomenda\u00e7\u00e3o
${d.recomendacao || '-'}

### Resumo
${d.resumo_operador || '-'}

### Status
- Guardrail: ${d.status_guardrail}
- LLM: ${d.status_llm === null || d.status_llm === undefined ? 'n\u00e3o consultado' : d.status_llm}
- Final: **${d.status_final}**
- Requer verifica\u00e7\u00e3o humana: ${d.requer_humano ? 'sim' : 'n\u00e3o'}

### Evid\u00eancias
${evidenciasParecer('manutencao')}

${evidenciasParecer('producao')}

${evidenciasParecer('energia')}

### Justificativa
${d.justificativa || '-'}

### Checklist sugerido
- [ ] Confirmar leitura no painel local da m\u00e1quina ${d.id_maquina}
- [ ] Inspecionar visualmente motor/rolamentos/ventila\u00e7\u00e3o
- [ ] Verificar quadro el\u00e9trico e conex\u00f5es
- [ ] Registrar a\u00e7\u00e3o tomada e hor\u00e1rio
- [ ] Encerrar ordem de servi\u00e7o ap\u00f3s normaliza\u00e7\u00e3o
`;

return [{ json: { ...$json, titulo_trello: titulo, descricao_trello: descricao } }];

return [{ json: {
  id_decisao: $json.id_decisao,
  canal: 'TELEGRAM',
  dry_run: 1,
  destino: $env.TELEGRAM_CHAT_ID,
  conteudo: JSON.stringify({ text: $json.mensagem_telegram }),
  sucesso: 1,
  erro: null
} }];

return [{ json: {
  id_decisao: $json.id_decisao,
  canal: 'EMAIL',
  dry_run: 1,
  destino: $env.EMAIL_DESTINO,
  conteudo: JSON.stringify({ assunto: $json.assunto_email, html: $json.html_email }),
  sucesso: 1,
  erro: null
} }];

return [{ json: {
  id_decisao: $json.id_decisao,
  canal: 'TRELLO',
  dry_run: 1,
  destino: $env.TRELLO_LIST_ID,
  conteudo: JSON.stringify({ nome: $json.titulo_trello, descricao: $json.descricao_trello }),
  sucesso: 1,
  erro: null
} }];

const ctx = $('Render Telegram').first().json;
return [{ json: {
  id_decisao: ctx.id_decisao,
  canal: 'TELEGRAM',
  dry_run: 0,
  destino: $env.TELEGRAM_CHAT_ID,
  conteudo: JSON.stringify({ text: ctx.mensagem_telegram }),
  sucesso: 1,
  erro: null
} }];

const ctx = $('Render Telegram').first().json;
return [{ json: {
  id_decisao: ctx.id_decisao,
  canal: 'TELEGRAM',
  dry_run: 0,
  destino: $env.TELEGRAM_CHAT_ID,
  conteudo: JSON.stringify({ text: ctx.mensagem_telegram }),
  sucesso: 0,
  erro: (typeof $json.error === 'string' ? $json.error : ($json.error && ($json.error.message || JSON.stringify($json.error))) || 'Erro desconhecido ao enviar')
} }];

const ctx = $('Render Email').first().json;
return [{ json: {
  id_decisao: ctx.id_decisao,
  canal: 'EMAIL',
  dry_run: 0,
  destino: $env.EMAIL_DESTINO,
  conteudo: JSON.stringify({ assunto: ctx.assunto_email, html: ctx.html_email }),
  sucesso: 1,
  erro: null
} }];

const ctx = $('Render Email').first().json;
return [{ json: {
  id_decisao: ctx.id_decisao,
  canal: 'EMAIL',
  dry_run: 0,
  destino: $env.EMAIL_DESTINO,
  conteudo: JSON.stringify({ assunto: ctx.assunto_email, html: ctx.html_email }),
  sucesso: 0,
  erro: (typeof $json.error === 'string' ? $json.error : ($json.error && ($json.error.message || JSON.stringify($json.error))) || 'Erro desconhecido ao enviar')
} }];

const ctx = $('Render Trello').first().json;
return [{ json: {
  id_decisao: ctx.id_decisao,
  canal: 'TRELLO',
  dry_run: 0,
  destino: $env.TRELLO_LIST_ID,
  conteudo: JSON.stringify({ nome: ctx.titulo_trello, descricao: ctx.descricao_trello }),
  sucesso: 1,
  erro: null
} }];

const ctx = $('Render Trello').first().json;
return [{ json: {
  id_decisao: ctx.id_decisao,
  canal: 'TRELLO',
  dry_run: 0,
  destino: $env.TRELLO_LIST_ID,
  conteudo: JSON.stringify({ nome: ctx.titulo_trello, descricao: ctx.descricao_trello }),
  sucesso: 0,
  erro: (typeof $json.error === 'string' ? $json.error : ($json.error && ($json.error.message || JSON.stringify($json.error))) || 'Erro desconhecido ao enviar')
} }];

// Fan-in: recebe 1 item "contexto" de Normalizar Entrada (sempre) e, quando
// aplicável, 1 item por canal efetivamente executado (com campo "canal").
// Ramos de canal não disparados (fora de acoes_previstas) chegam "pulados"
// (0 itens), então este nó roda mesmo com acoes_previstas = [] (status NORMAL).
const items = $input.all();
const contexto = items.find((it) => it.json.canal === undefined);
const acoesExecutadas = items
  .filter((it) => it.json.canal !== undefined)
  .map((it) => ({
    canal: it.json.canal,
    dry_run: !!it.json.dry_run,
    sucesso: !!it.json.sucesso
  }));

const idDecisao = contexto ? contexto.json.id_decisao : (items[0] ? items[0].json.id_decisao : null);

return [{ json: { id_decisao: idDecisao, acoes_executadas: acoesExecutadas } }];
